# v63 — editorial category accent system ----------------------------------
# Each category gets a deliberate accent color pulled from the institutional
# palette below, so the grid reads with real color variety instead of one
# blue tint repeated everywhere. Unlisted/custom categories fall back to a
# stable hash-based pick from the same palette, so they're still consistent
# across a page rather than random on every render.
CATEGORY_PALETTE = {
    "Markets": "#2F9BFF",
    "Legislation": "#E0447C",
    "Regulatory": "#E0447C",
    "Institutional": "#3F8F6E",
    "Technology": "#6C7BD1",
    "XRPL": "#6C7BD1",
    "Community": "#B65C8C",
    "General": "#8992A6",
}
_ACCENT_FALLBACKS = ["#2F9BFF", "#E0447C", "#3F8F6E", "#6C7BD1", "#B65C8C"]


def category_accent(category):
    if not category:
        return _ACCENT_FALLBACKS[0]
    if category in CATEGORY_PALETTE:
        return CATEGORY_PALETTE[category]
    idx = sum(ord(c) for c in category) % len(_ACCENT_FALLBACKS)
    return _ACCENT_FALLBACKS[idx]


def category_tint(category, alpha=0.12):
    hex_color = category_accent(category).lstrip("#")
    r, g, b = (int(hex_color[i:i + 2], 16) for i in (0, 2, 4))
    return f"rgba({r},{g},{b},{alpha})"


app.jinja_env.globals["cat_accent"] = category_accent
app.jinja_env.globals["cat_tint"] = category_tint

# ----------------------------------------------------------------------
# DATABASE
# ----------------------------------------------------------------------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            slug TEXT UNIQUE NOT NULL,
            title TEXT NOT NULL,
            excerpt TEXT,
            content TEXT NOT NULL,
            category TEXT DEFAULT 'General',
            published INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS images (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            post_id INTEGER NOT NULL,
            filename TEXT NOT NULL,
            FOREIGN KEY (post_id) REFERENCES posts (id)
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS site_stats (
            key TEXT PRIMARY KEY,
            value INTEGER NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS portal_items (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL,
            title TEXT NOT NULL,
            filename TEXT,
            body TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS subscribers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            created_at TEXT NOT NULL
        )
        """
    )
    conn.execute(
        "INSERT OR IGNORE INTO site_stats (key, value) VALUES ('visitor_count', 102394)"
    )
    conn.commit()
    conn.close()


init_db()

# ----------------------------------------------------------------------
# HELPERS
# ----------------------------------------------------------------------

def slugify(title):
    slug = title.lower().strip()
    slug = re.sub(r"[^a-z0-9]+", "-", slug)
    return slug.strip("-") or "post"


def unique_slug(title, exclude_id=None):
    db = get_db()
    base = slugify(title)
    slug = base
    n = 2
    while True:
        row = db.execute("SELECT id FROM posts WHERE slug = ?", (slug,)).fetchone()
        if row is None or (exclude_id is not None and row["id"] == exclude_id):
            return slug
        slug = f"{base}-{n}"
        n += 1


def allowed_file(filename):
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXT


def save_uploaded_images(post_id, files):
    db = get_db()
    for f in files:
        if not f or not f.filename or not allowed_file(f.filename):
            continue
        base = secure_filename(f.filename)
        name = base
        path = os.path.join(UPLOAD_DIR, name)
        n = 2
        while os.path.exists(path):
            root, ext = os.path.splitext(base)
            name = f"{root}-{n}{ext}"
            path = os.path.join(UPLOAD_DIR, name)
            n += 1
        f.save(path)
        db.execute("INSERT INTO images (post_id, filename) VALUES (?, ?)", (post_id, name))
    db.commit()


def render_content(content):
    """Replace {{img:filename}} tokens with actual image tags. Strips any
    <style>, <script>, <html>, <head>, <body> tags (and their content), any
    inline on*="" event-handler attributes, and any inline style="" attributes
    so a pasted full HTML document can never override this page's own CSS,
    inject scripts, or run inline event handlers \u2014 only the safe subset of
    tags used by our paste-ready format (h2, p, strong, em, hr, img) passes
    through untouched."""
    content = re.sub(r"(?is)<(style|script)\b[^>]*>.*?</\1>", "", content)
    content = re.sub(r"(?i)</?(html|head|body|meta|link|title|iframe|object|embed)\b[^>]*>", "", content)
    content = re.sub(r'(?i)\son[a-z]+\s*=\s*"[^"]*"', "", content)
    content = re.sub(r"(?i)\son[a-z]+\s*=\s*'[^']*'", "", content)
    content = re.sub(r'(?i)\sstyle\s*=\s*"[^"]*"', "", content)
    content = re.sub(r"(?i)\sstyle\s*=\s*'[^']*'", "", content)

    def repl(match):
        fname = match.group(1).strip()
        return f'<img src="/uploads/{fname}" alt="{fname}" class="post-img">'
    return re.sub(r"\{\{img:([^\}]+)\}\}", repl, content)


def login_required(f):
    @wraps(f)
    def wrapped(*args, **kwargs):
        if not session.get("admin"):
            return redirect(url_for("admin_login"))
        return f(*args, **kwargs)
    return wrapped


def uptime_str():
    secs = int(time.time() - START_TIME)
    h, rem = divmod(secs, 3600)
    m, s = divmod(rem, 60)
    return f"{h}h {m}m {s}s"


