@app.route("/")
def index():
    """v63 — the homepage is now a true magazine front page (one featured
    lead story + a grid of recent briefings) instead of the single latest
    post shown in full. Reuses INDEX_TEMPLATE's existing featured_layout
    mode rather than a separate template."""
    db = get_db()
    visitor_count = bump_visitor_count(db)
    posts = attach_thumbnails(db, db.execute(
        "SELECT * FROM posts WHERE published = 1 ORDER BY id DESC LIMIT 7").fetchall())
    recent_posts, categories = sidebar_context(db)
    return render_template_string(
        INDEX_TEMPLATE, posts=posts, heading="Latest Intelligence", nav_page="home",
        featured_layout=True,
        recent_posts=recent_posts, categories=categories, **footer_ctx(db, visitor_count)
    )


@app.route("/briefings")
def briefings():
    db = get_db()
    visitor_count = bump_visitor_count(db)
    all_posts = attach_thumbnails(db, db.execute(
        "SELECT * FROM posts WHERE published = 1 ORDER BY id DESC").fetchall())
    # V59: Briefings = titles containing "Brief" plus a number, or Proprietary
    # briefings. Other stories are not briefings and stay out of this page.
    def is_briefing(p):
        t = (p.get("title") or "")
        tl = t.lower()
        return ("brief" in tl) and (bool(re.search(r"\d", t)) or "proprietary" in tl)
    posts = [p for p in all_posts if is_briefing(p)]
    recent_posts, categories = sidebar_context(db)
    return render_template_string(
        INDEX_TEMPLATE, posts=posts, heading="Briefings", nav_page="briefings",
        subheading="Numbered XRP briefings and Proprietary Briefings, newest first.",
        featured_layout=False,
        recent_posts=recent_posts, categories=categories, **footer_ctx(db, visitor_count)
    )


